#include <bits/stdc++.h>

using namespace std;

using i64 = long long;

const i64 MOD = 1000000007;

struct Field {
  i64 v;
  Field(i64 x = 0) : v(x % MOD) {
    if (v < 0) v += MOD;
    if (v >= MOD) { cerr << "Field error\n"; exit(1); }
  }
  Field operator+(const Field& o) const { return Field((v + o.v) % MOD); }
  Field operator-(const Field& o) const { return Field((v - o.v + MOD) % MOD); }
  Field operator*(const Field& o) const { return Field((v * o.v) % MOD); }
  Field operator/(const Field& o) const { return (*this) * o.inv(); }
  Field& operator+=(const Field& o) { v = (v + o.v) % MOD; return *this; }
  Field& operator-=(const Field& o) { v = (v - o.v + MOD) % MOD; return *this; }
  Field& operator*=(const Field& o) { v = (v * o.v) % MOD; return *this; }
  Field& operator/=(const Field& o) { return (*this) *= o.inv(); }
  Field inv() const {
    i64 e = MOD - 2, b = v, r = 1;
    while (e) {
      if (e & 1) r = (r * b) % MOD;
      b = (b * b) % MOD;
      e >>= 1;
    }
    return Field(r);
  }
};

template<typename T>
vector<vector<T>> matmul(const vector<vector<T>>& A, const vector<vector<T>>& B) {
  int n = A.size(), m = A[0].size(), p = B[0].size();
  if (B.size() != m) { cerr << "matmul dim error\n"; exit(1); }
  vector<vector<T>> C(n, vector<T>(p));
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < p; ++j)
      for (int k = 0; k < m; ++k)
        C[i][j] = C[i][j] + A[i][k] * B[k][j];
  return C;
}

template<typename T>
vector<T> matvec(const vector<vector<T>>& A, const vector<T>& x) {
  int n = A.size(), m = A[0].size();
  if (x.size() != m) { cerr << "matvec dim error\n"; exit(1); }
  vector<T> y(n);
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < m; ++j)
      y[i] = y[i] + A[i][j] * x[j];
  return y;
}

template<typename T>
vector<vector<T>> matrix2D(int r, int c, const T& val = T()) {
  return vector<vector<T>>(r, vector<T>(c, val));
}

template<typename T>
vector<vector<vector<T>>> matrix3D(int a, int b, int c, const T& val = T()) {
  return vector<vector<vector<T>>>(a, vector<vector<T>>(b, vector<T>(c, val)));
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);

  i64 n;
  int d;
  cin >> n >> d;

  auto shift = matrix3D<Field>(d, d + 1, d + 1);
  for (int k = 0; k < d; ++k) {
    for (int i = 0; i < d; ++i)
      shift[k][i][(i + k) % d] = Field(1);
    shift[k][d][d] = Field(1);
  }

  auto unit = matrix3D<Field>(d, d + 1, d + 1);
  for (int k = 0; k < d; ++k) {
    for (int i = 0; i < d + 1; ++i)
      unit[k][i][i] = Field(1);
    for (int i = 0; i < d + 1; ++i)
      unit[k][k][i] = Field(1);
  }

  auto I = matrix2D<Field>(d + 1, d + 1);
  for (int i = 0; i < d + 1; ++i)
    I[i][i] = Field(1);

  unordered_map<i64, vector<vector<Field>>> cache;

  function<vector<vector<Field>>(i64)> build = [&](i64 p) -> vector<vector<Field>> {
    auto it = cache.find(p);
    if (it != cache.end()) return it->second;
    if (p <= d) {
      auto M = I;
      for (int k = 0; k < p; ++k)
        M = matmul(unit[k], M);
      return M;
    }
    i64 block = d;
    while ((p + block - 1) / block > d) block *= d;
    auto child = build(block);
    auto M = child;
    i64 rem = p - block;
    for (int k = 1; k < d; ++k) {
      if (rem >= block) {
        M = matmul(matmul(matmul(shift[d - k], child), shift[k]), M);
        rem -= block;
      } else if (rem > 0) {
        M = matmul(matmul(matmul(shift[d - k], build(rem)), shift[k]), M);
        rem = 0;
      } else break;
    }
    return cache[p] = M;
  };

  auto M = build(n);
  vector<Field> base(d + 1);
  base[d] = Field(1);
  auto ansVec = matvec(M, base);
  Field sum;
  for (auto& x : ansVec) sum += x;
  cout << sum.v << '\n';
}
